"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { ComponentProps, PointerEvent } from "react";

import { cn } from "@/lib/utils";
import { usePrefersReducedMotion } from "@/registry/ivan/hooks/use-prefers-reduced-motion";
import {
  ditherFrame,
  orderPalette,
  resolveColor,
} from "@/registry/ivan/lib/dither";
import type { DitherFrame } from "@/registry/ivan/lib/dither";
import { driftRows } from "@/registry/ivan/lib/dither-drift";
import type { DriftPointer } from "@/registry/ivan/lib/dither-drift";

const maxSourceSize = 480;
const driftBand = 0.16;
const driftEasing = 0.09;
const settledIntensity = 0.01;

const pixelated = { imageRendering: "pixelated" } as const;

const clampNumber = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const loadSource = async (src: string, crossOrigin: string | null) => {
  const image = new window.Image();
  if (crossOrigin !== null) {
    image.crossOrigin = crossOrigin;
  }
  image.src = src;
  try {
    await image.decode();
  } catch {
    return null;
  }
  const scale = Math.min(
    1,
    maxSourceSize / Math.max(image.naturalWidth, image.naturalHeight)
  );
  const width = Math.max(1, Math.round(image.naturalWidth * scale));
  const height = Math.max(1, Math.round(image.naturalHeight * scale));
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d", { willReadFrequently: true });
  if (!context) {
    return null;
  }
  context.drawImage(image, 0, 0, width, height);
  try {
    return {
      data: context.getImageData(0, 0, width, height).data,
      height,
      width,
    } satisfies DitherFrame;
  } catch {
    return null;
  }
};

const paintFrame = (canvas: HTMLCanvasElement, frame: DitherFrame) => {
  const context = canvas.getContext("2d");
  if (!context) {
    return;
  }
  canvas.width = frame.width;
  canvas.height = frame.height;
  context.putImageData(
    new ImageData(new Uint8ClampedArray(frame.data), frame.width, frame.height),
    0,
    0
  );
};

export interface DitherImageProps extends Omit<
  ComponentProps<"div">,
  "children"
> {
  src: string;
  alt: string;
  pixelSize?: number;
  contrast?: number;
  drift?: number;
  inkColor?: string;
  paperColor?: string;
  crossOrigin?: "anonymous" | "use-credentials" | null;
}

export const DitherImage = ({
  src,
  alt,
  pixelSize = 2,
  contrast = 14,
  drift = 11,
  inkColor = "--foreground",
  paperColor = "--background",
  crossOrigin = "anonymous",
  className,
  onPointerLeave,
  onPointerMove,
  ...props
}: DitherImageProps) => {
  const rootRef = useRef<HTMLDivElement>(null);
  const baseRef = useRef<HTMLCanvasElement>(null);
  const driftRef = useRef<HTMLCanvasElement>(null);
  const frameRef = useRef<DitherFrame | null>(null);
  const imageRef = useRef<ImageData | null>(null);
  const pointerRef = useRef<DriftPointer & { isInside: boolean }>({
    isInside: false,
    x: 0,
    y: 0,
  });
  const intensityRef = useRef(0);
  const requestRef = useRef<number | null>(null);
  const [isReady, setIsReady] = useState(false);
  const isReduced = usePrefersReducedMotion();
  const size = Math.round(clampNumber(pixelSize, 1, 8));
  const amplitude = isReduced ? 0 : clampNumber(drift, 0, 40);

  useEffect(() => {
    let isCancelled = false;
    const paint = async () => {
      const root = rootRef.current;
      const source = await loadSource(src, crossOrigin);
      const canvas = baseRef.current;
      if (isCancelled || !source || !root || !canvas) {
        return;
      }
      const palette = orderPalette(
        resolveColor(root, inkColor),
        resolveColor(root, paperColor)
      );
      const dithered = ditherFrame(source, palette, {
        contrast: clampNumber(contrast, 0, 60),
        pixelSize: size,
      });
      paintFrame(canvas, dithered);
      frameRef.current = dithered;
      setIsReady(true);
    };
    paint();
    return () => {
      isCancelled = true;
    };
  }, [src, crossOrigin, inkColor, paperColor, contrast, size]);

  const run = useCallback(() => {
    if (requestRef.current !== null) {
      return;
    }
    const step = (time: number) => {
      const canvas = driftRef.current;
      const frame = frameRef.current;
      const context = canvas?.getContext("2d");
      if (!(canvas && frame && context)) {
        requestRef.current = null;
        return;
      }
      const pointer = pointerRef.current;
      intensityRef.current +=
        ((pointer.isInside ? 1 : 0) - intensityRef.current) * driftEasing;
      if (!pointer.isInside && intensityRef.current < settledIntensity) {
        intensityRef.current = 0;
        canvas.dataset.active = "false";
        requestRef.current = null;
        return;
      }
      if (canvas.width !== frame.width || canvas.height !== frame.height) {
        canvas.width = frame.width;
        canvas.height = frame.height;
      }
      if (
        !imageRef.current ||
        imageRef.current.width !== frame.width ||
        imageRef.current.height !== frame.height
      ) {
        imageRef.current = context.createImageData(frame.width, frame.height);
      }
      driftRows(
        frame,
        imageRef.current.data,
        pointer,
        intensityRef.current,
        time,
        { amplitude, band: driftBand, cell: size }
      );
      context.putImageData(imageRef.current, 0, 0);
      canvas.dataset.active = "true";
      requestRef.current = requestAnimationFrame(step);
    };
    requestRef.current = requestAnimationFrame(step);
  }, [amplitude, size]);

  useEffect(
    () => () => {
      if (requestRef.current !== null) {
        cancelAnimationFrame(requestRef.current);
      }
    },
    []
  );

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    onPointerMove?.(event);
    const frame = frameRef.current;
    if (event.pointerType !== "mouse" || amplitude === 0 || !frame) {
      return;
    }
    const bounds = event.currentTarget.getBoundingClientRect();
    const scale = Math.max(
      bounds.width / frame.width,
      bounds.height / frame.height
    );
    const offsetX = (bounds.width - frame.width * scale) / 2;
    const offsetY = (bounds.height - frame.height * scale) / 2;
    pointerRef.current = {
      isInside: true,
      x: (event.clientX - bounds.left - offsetX) / scale,
      y: (event.clientY - bounds.top - offsetY) / scale,
    };
    run();
  };

  const handlePointerLeave = (event: PointerEvent<HTMLDivElement>) => {
    onPointerLeave?.(event);
    pointerRef.current = { ...pointerRef.current, isInside: false };
    run();
  };

  return (
    <div
      className={cn(
        "bg-muted relative aspect-4/5 overflow-hidden",
        amplitude > 0 && "cursor-crosshair",
        className
      )}
      data-ready={isReady}
      onPointerLeave={handlePointerLeave}
      onPointerMove={handlePointerMove}
      ref={rootRef}
      {...props}
    >
      <canvas
        aria-hidden
        className="absolute inset-0 block size-full object-cover opacity-0 transition-opacity duration-500 ease-out data-[ready=true]:opacity-100 motion-reduce:transition-none"
        data-ready={isReady}
        ref={baseRef}
        style={pixelated}
      />
      <canvas
        aria-hidden
        className="pointer-events-none invisible absolute inset-0 block size-full object-cover data-[active=true]:visible"
        data-active="false"
        ref={driftRef}
        style={pixelated}
      />
      {alt ? <span className="sr-only">{alt}</span> : null}
    </div>
  );
};

export type Rgb = readonly [number, number, number];

export interface DitherFrame {
  data: Uint8ClampedArray;
  height: number;
  width: number;
}

export interface DitherPalette {
  dark: Rgb;
  light: Rgb;
}

export interface DitherOptions {
  contrast: number;
  pixelSize: number;
}

export const BAYER_SIDE = 4;

const TONE_CONTRAST = 18;
const TONE_BRIGHTNESS = 8;

const clampByte = (value: number) => Math.min(255, Math.max(0, value));

const contrastFactor = (contrast: number) => {
  const scaled = contrast * 2.55;
  return (259 * (scaled + 255)) / (255 * (259 - scaled));
};

const buildBayerThresholds = () => {
  let current = [0];
  let side = 1;
  while (side < BAYER_SIDE) {
    const doubled = side * 2;
    const next: number[] = Array.from({ length: doubled * doubled }, () => 0);
    for (let y = 0; y < side; y += 1) {
      for (let x = 0; x < side; x += 1) {
        const value = (current[y * side + x] ?? 0) * 4;
        next[y * doubled + x] = value;
        next[y * doubled + x + side] = value + 2;
        next[(y + side) * doubled + x] = value + 3;
        next[(y + side) * doubled + x + side] = value + 1;
      }
    }
    current = next;
    side = doubled;
  }
  return current.map((value) => (value + 0.5) / current.length);
};

export const bayerThresholds: readonly number[] = buildBayerThresholds();

export const bayerThreshold = (x: number, y: number) =>
  bayerThresholds[(y % BAYER_SIDE) * BAYER_SIDE + (x % BAYER_SIDE)] ?? 0.5;

export const luminance = ([red, green, blue]: Rgb) =>
  0.2126 * red + 0.7152 * green + 0.0722 * blue;

export const orderPalette = (first: Rgb, second: Rgb): DitherPalette =>
  luminance(first) <= luminance(second)
    ? { dark: first, light: second }
    : { dark: second, light: first };

export const resolveColor = (element: Element, color: string): Rgb => {
  const probe = document.createElement("canvas");
  probe.width = 1;
  probe.height = 1;
  const context = probe.getContext("2d", { willReadFrequently: true });
  if (!context) {
    return [0, 0, 0];
  }
  context.fillStyle = color.startsWith("--")
    ? getComputedStyle(element).getPropertyValue(color).trim()
    : color;
  context.fillRect(0, 0, 1, 1);
  const [red = 0, green = 0, blue = 0] = context.getImageData(0, 0, 1, 1).data;
  return [red, green, blue];
};

const pixelLuminance = (data: Uint8ClampedArray, index: number) =>
  luminance([data[index] ?? 0, data[index + 1] ?? 0, data[index + 2] ?? 0]);

const blockTone = (
  frame: DitherFrame,
  blockX: number,
  blockY: number,
  pixelSize: number,
  toneFactor: number,
  ditherFactor: number
) => {
  const x0 = blockX * pixelSize;
  const y0 = blockY * pixelSize;
  const x1 = Math.min(x0 + pixelSize, frame.width);
  const y1 = Math.min(y0 + pixelSize, frame.height);
  let sum = 0;
  for (let y = y0; y < y1; y += 1) {
    for (let x = x0; x < x1; x += 1) {
      const level = pixelLuminance(frame.data, (y * frame.width + x) * 4);
      sum += clampByte(toneFactor * (level - 128) + 128 + TONE_BRIGHTNESS);
    }
  }
  const average = sum / ((x1 - x0) * (y1 - y0));
  return clampByte((average - 128) * ditherFactor + 128);
};

export const ditherFrame = (
  frame: DitherFrame,
  palette: DitherPalette,
  { contrast, pixelSize }: DitherOptions
): DitherFrame => {
  const toneFactor = contrastFactor(TONE_CONTRAST);
  const ditherFactor = contrastFactor(contrast);
  const blocksWide = Math.ceil(frame.width / pixelSize);
  const blocksHigh = Math.ceil(frame.height / pixelSize);
  const lightBlocks = new Uint8Array(blocksWide * blocksHigh);
  for (let blockY = 0; blockY < blocksHigh; blockY += 1) {
    for (let blockX = 0; blockX < blocksWide; blockX += 1) {
      const tone =
        blockTone(frame, blockX, blockY, pixelSize, toneFactor, ditherFactor) /
        255;
      lightBlocks[blockY * blocksWide + blockX] =
        tone > bayerThreshold(blockX, blockY) ? 1 : 0;
    }
  }
  const data = new Uint8ClampedArray(frame.width * frame.height * 4);
  for (let y = 0; y < frame.height; y += 1) {
    const row = Math.floor(y / pixelSize) * blocksWide;
    for (let x = 0; x < frame.width; x += 1) {
      const color = lightBlocks[row + Math.floor(x / pixelSize)]
        ? palette.light
        : palette.dark;
      data.set([...color, 255], (y * frame.width + x) * 4);
    }
  }
  return { data, height: frame.height, width: frame.width };
};

import type { DitherFrame } from "./dither";

export interface DriftPointer {
  x: number;
  y: number;
}

export interface DriftSettings {
  amplitude: number;
  band: number;
  cell: number;
}

export const driftRows = (
  source: DitherFrame,
  target: Uint8ClampedArray,
  pointer: DriftPointer,
  intensity: number,
  time: number,
  { amplitude, band, cell }: DriftSettings
) => {
  const { data, height, width } = source;
  const rowBytes = width * 4;
  const bandHeight = Math.max(1, height * band);
  const lean = ((pointer.x - width / 2) / width) * amplitude;
  for (let y = 0; y < height; y += 1) {
    const row = Math.floor(y / cell);
    const distance = (y - pointer.y) / bandHeight;
    const falloff = Math.exp(-distance * distance);
    const wave =
      Math.sin(time * 0.008 + row * 0.9) +
      0.5 * Math.sin(time * 0.013 - row * 0.37);
    const shift =
      Math.round((intensity * falloff * (amplitude * wave + lean)) / cell) *
      cell;
    const start = y * rowBytes;
    const offset = ((shift % width) + width) % width;
    target.set(
      data.subarray(start + (width - offset) * 4, start + rowBytes),
      start
    );
    target.set(
      data.subarray(start, start + (width - offset) * 4),
      start + offset * 4
    );
  }
};

"use client";

import { useSyncExternalStore } from "react";

const reducedMotionQuery = "(prefers-reduced-motion: reduce)";

const subscribe = (onChange: () => void) => {
  const mediaQuery = window.matchMedia(reducedMotionQuery);
  mediaQuery.addEventListener("change", onChange);
  return () => mediaQuery.removeEventListener("change", onChange);
};

const getSnapshot = () => window.matchMedia(reducedMotionQuery).matches;

const getServerSnapshot = () => false;

export const usePrefersReducedMotion = () =>
  useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
